    }
    let mut requirements = discover(&root)?;
    if let Some(id) = options.get("--requirement") {
        requirements.retain(|r| &r.id == id);
        if requirements.is_empty() {
            return Err(format!("unknown requirement {id}"));
        }
    }
    if command == "requirements" {
